import re
from itertools import product

states = ['q0', 'q1']
start = 'q0'
final = {'q0'}
delta = {('q0','0'):'q0', ('q0','1'):'q1', ('q1','0'):'q1', ('q1','1'):'q0'}
pattern = re.compile(r'0*(10*10*)*')

def dfa_accepts(w):
    s = start
    for ch in w:
        s = delta[(s, ch)]
    return s in final

count = 0
for n in range(4):
    for tup in product('01', repeat=n):
        w = ''.join(tup)
        a = dfa_accepts(w)
        b = bool(pattern.fullmatch(w))
        assert a == b, w
        if a:
            count += 1

print(count)
